using LedgerFlow.Api.Models;namespace LedgerFlow.Api.Services;public sealed class ReconciliationService{public(TransactionStatus Status,string Reason)Evaluate(Transaction transaction){if(transaction.Amount<=0)return(TransactionStatus.Exception,"Amount must be greater than zero.");if(string.IsNullOrWhiteSpace(transaction.Account))return(TransactionStatus.Exception,"Account identifier is missing.");if(transaction.BookedAt>DateTimeOffset.UtcNow.AddMinutes(5))return(TransactionStatus.Exception,"Booking timestamp is in the future.");return(TransactionStatus.Matched,"Passed deterministic reconciliation checks.");}}
